import math
from dataclasses import dataclass


@dataclass
class Point:
    x: float
    y: float


@dataclass
class Employee:
    name: str
    department: str
    salary: float

    def __post_init__(self):
        if self.salary < 0:
            raise ValueError("Salary cannot be negative")


def distance(p1, p2):
    return math.sqrt((p2.x - p1.x) ** 2 + (p2.y - p1.y) ** 2)
